<?php
namespace App\Listeners; use App\Domain\GhostEvents\Services\GhostEventService; use App\Domain\Missions\Services\SeasonMissionService; use App\Domain\Notifications\Services\NotificationService; use App\Domain\Observability\Services\MetricsService; use App\Domain\Races\Events\RankedRunAccepted; use App\Domain\Retention\StreakService; use App\Domain\Tournaments\Services\TournamentService;
class CompetitiveRunAcceptedListener { public function __construct(private readonly TournamentService $tournaments,private readonly GhostEventService $ghosts,private readonly SeasonMissionService $missions,private readonly StreakService $streaks,private readonly NotificationService $notifications,private readonly MetricsService $metrics){} public function handle(RankedRunAccepted $e):void{$r=$e->run;$this->tournaments->recordAcceptedAttempt($r);$this->ghosts->recordAccepted($r);if($r->raceSession?->mode==='practice')return;$this->recordSeasonRating($r);$this->missions->progressFromEvent($r->user,'RankedRunAccepted',1,['dedupeKey'=>'run:'.$r->id]);$this->streaks->recordQualifyingAction($r->user,now('UTC'));$this->notifications->create($r->user,'submission_accepted','Run accepted','Your competitive run was verified.',null,['dedupe_key'=>'accepted-run:'.$r->id]);$this->metrics->increment('ranked_runs_accepted');} private function recordSeasonRating($run):void{\Illuminate\Support\Facades\DB::table('season_participants')->join('seasons','seasons.id','=','season_participants.season_id')->where('season_participants.user_id',$run->user_id)->where('seasons.status','active')->update(['season_participants.accepted_ranked_runs'=>\Illuminate\Support\Facades\DB::raw('accepted_ranked_runs + 1'),'season_participants.total_ranked_runs'=>\Illuminate\Support\Facades\DB::raw('total_ranked_runs + 1'),'season_participants.current_rating'=>\Illuminate\Support\Facades\DB::raw('current_rating + 1'),'season_participants.peak_rating'=>\Illuminate\Support\Facades\DB::raw('CASE WHEN peak_rating >= current_rating + 1 THEN peak_rating ELSE current_rating + 1 END'),'season_participants.updated_at'=>now()]);} }
